def strip_zones(text):
    for start, end in ZONES:
        if start in text and end in text:
            a = text.index(start)
            b = text.index(end) + len(end)
            text = text[:a] + text[b:]
    return text


def fingerprint(data):
    text = data.replace(b"\r\n", b"\n").decode("utf-8")
    return hashlib.md5(strip_zones(text).encode("utf-8")).hexdigest()


def fail(msg):
    print("FAILURE: " + msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    if os.path.basename(os.getcwd()) == "documentation" or \
            os.path.basename(HERE) == "documentation":
        fail("this is running from documentation/. Run it from the orrery "
             "repo root, then file it in documentation/.")
    if not os.path.exists(os.path.join(HERE, "palomas_orrery.py")):
        fail("palomas_orrery.py is not beside this script. Save it in the "
             "ORRERY repo root.")
    results = []
    for rel, fp, edits in TARGETS:
        path = os.path.join(HERE, rel)
        if not os.path.exists(path):
            fail("%s not found" % rel)
        with open(path, "rb") as handle:
            raw = handle.read()
        got = fingerprint(raw)
        if got != fp:
            fail("%s is not the file this patch was built on (fingerprint "
                 "%s, expected %s). Pull or discard local changes first."
                 % (rel, got, fp))
        crlf = raw.count(b"\r\n") > 0
        text = raw.decode("utf-8")
        for label, old, new in edits:
            if crlf:
                old = old.replace("\n", "\r\n")
                new = new.replace("\n", "\r\n")
            n = text.count(old)
            if n != 1:
                fail('%s: "%s" -- expected 1 match, got %d' % (rel, label, n))
            text = text.replace(old, new)
            print("ok    %s: %s" % (rel, label))
        try:
            text.encode("ascii")
        except UnicodeEncodeError as exc:
            fail("%s would not be ASCII after the patch (%s)" % (rel, exc))
        results.append((path, text.encode("utf-8")))
    new_out = []
    for rel, md5, blob in NEW_FILES:
        path = os.path.join(HERE, rel)
        data = zlib.decompress(base64.b64decode(blob))
        if hashlib.md5(data).hexdigest() != md5:
            fail("the embedded %s does not match its checksum" % rel)
        if os.path.exists(path):
            # Already filed by hand is fine when it is the same document;
            # only a DIFFERENT file of that name stops the patch. (The
            # first version of this patch refused any existing file, and
            # these two had already been filed, so it wrote nothing.)
            with open(path, "rb") as handle:
                there = handle.read().replace(b"\r\n", b"\n")
            if there != data:
                fail("%s already exists and differs from the copy in this "
                     "patch" % rel)
            print("ok    %s: already filed, identical, left as it is"
                  % rel)
            continue
        new_out.append((path, data))
        print("ok    %s: new, %d bytes" % (rel, len(data)))
    for path, data in results + new_out:
        with open(path, "wb") as handle:
            handle.write(data)
    print("PATCH APPLIED: %d files changed, %d new." % (len(results),
                                                        len(new_out)))
    print("CHECK: skills/provenance-discipline/SKILL.md now reads 2.22 and "
          "skills/interactive-exhibit/SKILL.md 1.5.")
    print(NEXT_STEPS)


if __name__ == "__main__":
    main()
